export class BudgetExceeded extends Error {
  constructor(message: string) {
    super(message);
    this.name = "BudgetExceeded";
  }
}

export interface Reservation {
  commit(actualUsd: number): void;
  release(): void;
}

const EPS = 1e-9;

function checkUsd(usd: number, what: string): void {
  if (!Number.isFinite(usd) || usd < 0) throw new RangeError(`${what} must be a finite number >= 0, got ${usd}`);
}

/**
 * Hard spend caps per run and per task. Reservations are held until committed or released.
 * All state changes are synchronous, so reserve() is atomic under async concurrency.
 */
export class BudgetGuard {
  private spent = 0;
  private held = 0;
  private readonly taskSpent = new Map<string, number>();
  private readonly taskHeld = new Map<string, number>();

  constructor(private readonly runCapUsd: number, private readonly taskCapUsd: number) {
    checkUsd(runCapUsd, "runCapUsd");
    checkUsd(taskCapUsd, "taskCapUsd");
  }

  reserve(task: string, usd: number): Reservation {
    checkUsd(usd, "usd");
    const taskTotal = (this.taskSpent.get(task) ?? 0) + (this.taskHeld.get(task) ?? 0) + usd;
    if (this.held + this.spent + usd > this.runCapUsd + EPS) {
      throw new BudgetExceeded(`run cap $${this.runCapUsd} would be exceeded by reserving $${usd} for ${task}`);
    }
    if (taskTotal > this.taskCapUsd + EPS) {
      throw new BudgetExceeded(`task cap $${this.taskCapUsd} would be exceeded by reserving $${usd} for ${task}`);
    }
    this.held += usd;
    this.taskHeld.set(task, (this.taskHeld.get(task) ?? 0) + usd);

    let settled = false;
    const settle = (actual: number, verb: string): void => {
      if (settled) throw new Error(`reservation for ${task} already settled; cannot ${verb}`);
      settled = true;
      this.held = Math.max(0, this.held - usd);
      this.taskHeld.set(task, Math.max(0, (this.taskHeld.get(task) ?? 0) - usd));
      this.spent += actual;
      this.taskSpent.set(task, (this.taskSpent.get(task) ?? 0) + actual);
    };
    return {
      commit: (actualUsd: number) => {
        if (settled) throw new Error(`reservation for ${task} already settled; cannot commit`);
        checkUsd(actualUsd, "actualUsd");
        settle(actualUsd, "commit");
      },
      release: () => settle(0, "release"),
    };
  }

  /** Committed spend so far. */
  used(): number {
    return this.spent;
  }

  /** Run budget not yet spent or reserved; never negative. */
  remaining(): number {
    return Math.max(0, this.runCapUsd - this.spent - this.held);
  }
}
EOF
cat > tests/budget.test.ts <<'EOF'
import { describe, expect, test } from "bun:test";
import { BudgetExceeded, BudgetGuard } from "../src/harness/budget";

describe("BudgetGuard", () => {
  test("reserve counts against remaining; commit replaces with actual", () => {
    const g = new BudgetGuard(10, 5);
    const r = g.reserve("a", 4);
    expect(g.used()).toBe(0);
    expect(g.remaining()).toBe(6);
    r.commit(1.5);
    expect(g.used()).toBe(1.5);
    expect(g.remaining()).toBe(8.5);
  });

  test("release frees the reservation", () => {
    const g = new BudgetGuard(10, 5);
    g.reserve("a", 5).release();
    expect(g.remaining()).toBe(10);
    expect(() => g.reserve("a", 5)).not.toThrow();
  });

  test("run cap includes outstanding reservations and used", () => {
    const g = new BudgetGuard(10, 8);
    g.reserve("a", 6);
    expect(() => g.reserve("b", 5)).toThrow(BudgetExceeded);
    expect(() => g.reserve("b", 4)).not.toThrow();
    expect(() => g.reserve("c", 0.01)).toThrow(BudgetExceeded);
  });

  test("task cap spans reservations and committed spend for that task", () => {
    const g = new BudgetGuard(100, 5);
    g.reserve("a", 3).commit(3);
    expect(() => g.reserve("a", 2.5)).toThrow(BudgetExceeded);
    expect(() => g.reserve("a", 2)).not.toThrow();
    expect(() => g.reserve("b", 5)).not.toThrow();
  });

  test("actual may exceed the reservation and still counts", () => {
    const g = new BudgetGuard(10, 5);
    g.reserve("a", 2).commit(4);
    expect(g.used()).toBe(4);
    g.reserve("b", 5).commit(7);
    expect(g.remaining()).toBe(0);
    expect(() => g.reserve("c", 0.5)).toThrow(BudgetExceeded);
  });

  test("double commit/release throws and does not double-count", () => {
    const g = new BudgetGuard(10, 5);
    const r = g.reserve("a", 2);
    r.commit(1);
    expect(() => r.commit(1)).toThrow();
    expect(() => r.release()).toThrow();
    const s = g.reserve("a", 2);
    s.release();
    expect(() => s.release()).toThrow();
    expect(() => s.commit(1)).toThrow();
    expect(g.used()).toBe(1);
    expect(g.remaining()).toBe(9);
  });

  test("rejects invalid amounts without reserving", () => {
    const g = new BudgetGuard(10, 5);
    expect(() => g.reserve("a", -1)).toThrow();
    expect(() => g.reserve("a", NaN)).toThrow();
    const r = g.reserve("a", 1);
    expect(() => r.commit(-1)).toThrow();
    r.commit(1);
    expect(g.used()).toBe(1);
  });

  test("concurrent reservations never overshoot the run cap", async () => {
    const g = new BudgetGuard(10, 10);
    let ok = 0;
    await Promise.all(
      Array.from({ length: 50 }, async (_, i) => {
        await Promise.resolve();
        try {
          const r = g.reserve(`t${i}`, 1);
          ok++;
          await new Promise((res) => setTimeout(res, 1));
          r.commit(1);
        } catch (e) {
          expect(e).toBeInstanceOf(BudgetExceeded);
        }
      }),
    );
    expect(ok).toBe(10);
    expect(g.used()).toBe(10);
  });
});
